// 가격은 "보통 범위"만 넣음 — 매장·드럼 크기마다 다르므로 화면에 항상 "기계 가격표 확인" 안내를 함께 보여 줌.
// 출처가 약한 도시(호놀룰루·토론토 등)는 넣지 않음. 6개월마다 다시 확인.
import type { Locale } from '../i18n';

export const LAUNDRY_REVIEWED = '2026-11';

export type Pay = 'coins' | 'notes' | 'card' | 'ic' | 'qr' | 'app';
export type Region = 'asia' | 'europe' | 'americas';
type L10n = Record<Locale, string>;

export interface CountryLaundry {
  currency: string;
  wash: [number, number]; // 세탁 1회 (표준 7–10kg)
  dry?: { price: [number, number]; per: number }; // 건조기: per 분당 가격
  dryCycle?: [number, number]; // 건조기: 1회(약 30분) 가격
  total?: [number, number]; // 세탁+건조 합계
  dropOffKg?: [number, number]; // 맡기는 세탁 kg당 (셀프가 드문 나라)
  pay: Pay[];
  hours: 'h24' | 'late' | 'day';
  detergent: 'auto' | 'buy' | 'mixed';
  rare?: boolean; // 셀프 빨래방이 드묾
  chains: string[];
  term: string; // 현지 간판·검색어
  tip: L10n;
}

export interface City {
  id: string;
  country: string; // ISO 3166-1
  region: Region;
  wash?: [number, number]; // 나라 평균과 다를 때
  name: L10n;
  tip: L10n;
}

