/** 주소용 도시 이름: 소문자·공백은 하이픈 (예: "New York" → "new-york", "호치민" → "호치민") */
export const citySlug = (city: City, lang: Locale) => city.name[lang].toLowerCase().replace(/\s+/g, '-');
